(function(root){
'use strict';
const e=x=>String(x??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const tabs=[['customers','公司客户'],['customer-contacts','联系人'],['customer-research','背景档案'],['customer-followups','跟进记录']];
function render(s,page){const rows=(s.acquisition?.companies||[]).filter(c=>c.source==='crm'||c.customer),current=rows.find(c=>c.id===s.acquisition?.selectedCompany);
 const nav=`<nav class="task-tabs">${tabs.map(([id,title])=>`<button data-action="navigate" data-page="${id}" class="${page===id?'selected':''}">${title}</button>`).join('')}</nav>`;
 if(page==='customer-detail')return `<div class="acquisition"><button data-action="navigate" data-page="customers">返回</button><section class="card"><h2>${e(current?.name||'客户资料')}</h2>${current?`<p>${e(current.country)} · ${e(current.domain)} · 来源：${e(current.reference||current.source)}</p><form data-form="customerSave" class="field-grid"><input type="hidden" name="id" value="${e(current.id)}"><label>联系人姓名<input name="person" maxlength="120" value="${e(current.person)}"></label><label>职务<input name="role" maxlength="160" value="${e(current.role)}"></label><label>业务邮箱<input type="email" name="email" maxlength="254" value="${e(current.email)}"></label><label>客户阶段<select name="stage">${['待了解','潜在客户','洽谈中','已成交','暂停跟进'].map(x=>`<option ${current.stage===x?'selected':''}>${x}</option>`).join('')}</select></label><label class="span2">本次跟进记录<textarea name="note" maxlength="3000" rows="3" placeholder="记录需求、沟通结果与下一步"></textarea></label><div class="span2 page-actions"><button class="primary">保存客户资料</button></div></form><h3>背景资料</h3><p>${e(current.fact||'待补充')}</p><p>${e(current.fit||'尚未分析')}</p><small>${e(current.unknown||'事实仍需核对')}</small><h3>跟进历史</h3>${(current.followups||[]).map(f=>`<p>${e(f.at)}<br>${e(f.note)}</p>`).join('')||'<p>暂无跟进记录</p>'}`:'<p>请选择客户</p>'}</section></div>`;
 const headers=page==='customer-contacts'?['公司','联系人 / 职务','业务邮箱','操作']:page==='customer-research'?['公司','已知事实','匹配与待核实','操作']:page==='customer-followups'?['公司','最近跟进','客户阶段','操作']:['公司 / 地区','官网 / 来源','联系人 / 阶段','操作'];
 return `${nav}<section class="card acquisition"><div class="acq-heading"><div><h2>${tabs.find(t=>t[0]===page)?.[1]||'公司客户'}</h2><p class="small muted">公司、联系人、背景资料与跟进共用一份客户记录；已有客户不重复计为新增线索。</p></div><button class="primary" data-action="navigate" data-page="customer-new">添加客户</button></div><div class="table-scroll"><table><thead><tr>${headers.map(h=>`<th>${h}</th>`).join('')}</tr></thead><tbody>${rows.map(c=>{const values=page==='customer-contacts'?[c.name,[c.person,c.role].filter(Boolean).join(' / '),c.email||'待补邮箱']:page==='customer-research'?[c.name,c.fact||'待补充',[c.fit,c.unknown].filter(Boolean).join('；')]:page==='customer-followups'?[c.name,c.followups?.[0]?.note||'暂无跟进',c.stage||'待了解']:[[c.name,c.country].join(' · '),[c.domain,c.reference||c.source].filter(Boolean).join(' / '),[c.person,c.stage||'待了解'].filter(Boolean).join(' / ')];return `<tr>${values.map(v=>`<td style="max-width:28rem;overflow-wrap:anywhere">${e(v)}</td>`).join('')}<td><button data-action="customerOpen" data-id="${e(c.id)}">查看客户</button></td></tr>`;}).join('')||'<tr><td colspan="4">暂无客户，可手工添加，也可从获客线索转入。</td></tr>'}</tbody></table></div></section>`;
}
function apply(s,type,p){const a=s.acquisition||(s.acquisition={companies:[],tasks:[]});const c=a.companies.find(c=>c.id===p.id);if(!c)throw Error('客户不存在');if(type==='customerOpen'){a.selectedCompany=c.id;return;}if(type==='customerPromote'){c.customer=true;c.stage=c.stage||'待了解';return;}if(type!=='customerSave')throw Error('未知客户操作');if(p.email&&!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(p.email))throw Error('业务邮箱格式无效');if(!['待了解','潜在客户','洽谈中','已成交','暂停跟进'].includes(p.stage))throw Error('客户阶段无效');for(const k of ['person','role','email','stage'])c[k]=String(p[k]||'').trim();if(p.note?.trim())c.followups=[{at:new Date().toISOString(),note:p.note.trim()},...(c.followups||[])].slice(0,200);}
const api={render,apply};if(typeof module!=='undefined'&&module.exports)module.exports=api;else root.LGACustomerView=api;
})(typeof globalThis!=='undefined'?globalThis:this);
